export default function Fullpage({
  params,
}: {
  params: { id: string; name: string };
}) {
  return (
    <div className="flex felx-col">
      <h1 className="text-2xl">full page view</h1>
      <p>Pokemon id: {params.id} </p>
      <p> pokemon name: {params.name} </p>
    </div>
  );
}
